def round_half_to_even(n):
    """
    Round half to even (banker's rounding).

    :param n:
        The number to round.
    :return:
        The rounded number.
    """
    if n % 1 == 0.5:
        return round(n - 0.5) if n > 0 else round(n + 0.5)
    else:
        return round(n)

def round_half_to_even(n):
    """
    Rounds half way to the nearest even number.

    :param n:
    :return:
    """
    if n < 0:
        return ceil(n) if n % 2 == -1 else floor(n - 1)
    elif n > 0:
        return floor(n + 1) if n % 2 == 1 else ceil(n)
    else:
        return 0

