def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Args:
        name: The name of the Point subclass.
        fields: A list of field names to include in the Point subclass.
        srid_map: A map of SRS names to their corresponding codes.

    Returns:
        The newly created Point subclass.
    """
    def make_dataclass(cls_name, fields, *, bases=(), namespace=None, init=True,
                       repr=True, eq=True, order=False, unsafe_hash=False,
                       frozen=False):
        """Return a new dynamically created dataclass.

        The dataclass name will be 'cls_name'.  'fields' is an iterable
        of either (name), (name, type) or (name, type, Field) objects. If type is
        omitted, use the string 'typing.Any'.  Field objects are created by
        the equivalent of calling 'field(name, type [, Field-info])'.

        @dataclass
        class C(Base):
            x: 'typing.Any'
            y: int
            z: int = field(init=False)

        For the bases and namespace parameters, see the builtin type() function.

        The parameters init, repr, eq, order, unsafe_hash, and frozen are passed to
        dataclass().
        """

        if namespace is None:
            namespace = {}
        else:
            # Copy namespace since we're going to mutate it.
            namespace = namespace.copy()

        # While we're looking through the field names, validate that they
        # are identifiers, are not keywords, and not duplicates.
        seen = set()
        anns = {}
        for item in fields:
            if isinstance(item, str):
                name = item
                tp = 'typing.Any'
            elif len(item) == 2:
                name, tp = item
            elif len(item) == 3:
                name, tp, spec = item
                namespace[name] = spec
            else:
                raise TypeError(f'Invalid field: {item!r}')

            if not isinstance(name, str) or not name.isidentifier():
                raise TypeError(f'Field names must be valid identifiers: {name!r}')
            if keyword.iskeyword(name):
                raise TypeError(f'Field names must not be keywords: {name!r}')
            if name in seen:
                raise TypeError(f'Field name duplicated: {name!r}')

        namespace['__annotations__'] = anns
        # We use `types.new_class()` instead of simply `type()` to allow dynamic creation
        # of generic dataclassses.
        cls = types.new_class(cls_name, bases, {}, lambda ns: ns.update(namespace))
        return dataclass(cls, init=init, repr=repr, eq=eq, order=order,
                     unsafe_hash=unsafe_hash, frozen=frozen)

    class Point(cls_name):
        def __init__(self, *args, **kwds):
            for name, value in zip(fields, args if args else [], **kwds):
                setattr(self, name, value)
            if srid_map:
                self.srid = srid_map.get(self.sridname)
            super().__init__()

        def __repr__(self):
            return f"{cls_name}({', '.join(f'{k}={v!r}' for k, v in self.__dict__.items())})"

    return make_dataclass(Point, fields)

