        def foo(x):
            pass

    """
    def _deprecated_wrapper(depfunc):
        if callable(depfunc):
            @functools.wraps(depfunc)
            def _inner(*args, **kwargs):
                warnings.warn(message)
                return depfunc(*args, **kwargs)
            return _inner
        else:
