import traceback

from typing import Any

def extostr(cls, e, max_level=30, max_path_level=5) -> str:
    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)
    path = ''
    line = ''
    name = ''
    src = None
    if tbinfo:
        path, line, name, src = tbinfo[-1]
    retz = {
        'msg': str(e),
        'file': path,
        'line': line,
        'name': name,
        'src': src
    }

    if isinstance(e, ValueError):
        retz['value'] = str(e)
    elif isinstance(e, TypeError):
        retz['type'] = str(type(e))
        retz['msg'] = "{} mismatched types {} and {}".format(type(e).__name__, str(e.args[0]), str(e.args[1]))
    elif isinstance(e, OSError):
        retz['oserr'] = str(e.errno)
        retz['desc'] = str(e.strerror)
    elif isinstance(e, Exception):
        retz['exc'] = e.__class__.__name__
    elif isinstance(e, str):
        retz['msg'] = e

    if isinstance(e, s_exc.SynErr):
        retz['syn:err'] = e.errinfo

    return cls._format_exc(retz, max_level, max_path_level)

