def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""

    # Check if self is an instance of the class with an internal attribute `attributes`
    if not hasattr(self, "attributes"):
        raise AttributeError("self must be an instance of a class with an internal `attributes` attribute")

    attributeNames = [attribute for attribute in self.attributes if attribute not in ["__class__"]]

    descriptions = {}
    for attribute in attributeNames:
        description = getattr(self, attribute + "_description")
        descriptions[attribute] = description

    if not all:
        return attributeNames
    else:
        return (attributeNames, descriptions)

def namesAndDescriptions(self, all=False):
    """
    Return attribute names and descriptions defined by interface.

    Parameters:
      all (bool): If True, include all attributes, otherwise only include public attributes.

    Returns:
      A dictionary containing attribute names as keys and their descriptions as values.
    """
    result = {}
    for attribute, value in self.__dict__.items():
        if all or not attribute.startswith("_"):
            result[attribute] = self.__module__ + "." + attribute
    return result

