def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """

    if output is None:
        output = []

    try:
        if isinstance(sequence, Declarions):
            output.extend(sequence.get_base_declarations())
            return

        if isinstance(sequence, tuple):
            output.extend(sequence)

        if isinstance(sequence, Interface):
            if InterfaceClass in sequence.__mro__ or zope.interface.declarations.Implements in sequence.__mro__:
                output.append(sequence)
            else:
                for v in sequence:
                    _normalizeargs(v, output)

        if isinstance(sequence, list):
            for s in sequence:
                _normalizeargs(s, output)
    except Exception as e:
        print(f"Error normalizing sequence: {e}")
        pass

