def _c_optimizations_available():
    """Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """

    available = False

    # Check if the C optimization library is installed
    try:
        ctypes.CDLL('cblas')
        available = True
    except OSError:
        pass

    if not available:
        try:
            ctypes.CDLL('mkl_lapacke')
            available = True
        except OSError:
            pass

    if not available:
        raise ImportError("C optimization libraries are not installed")

    return available

