    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.coords:
        raise ValueError(f"Coordinate '{coord_name}' not found.")
    try:
        min_error = np.inf
        err_indices = []
        for err, var in self.coords[coord_name].errors.items():
            if err < min_error:
                min_error = err
                err_indices = [var.indexes[0]]
            elif err == min_error:
                err_indices.append(var.indexes[0])
        return err_indices
    except AttributeError:
        raise ValueError(f"Error indices for coordinate '{coord_name}' not found.")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""

    def _find_indices_from_chaining(index器, error_name):
        for var in coord_names:
            error = indexer[var].attrs[error_name]
            iidx = error >= 0
            edd = error[iidx]

            for j, val in enumerate(edd):
                if np.isnan(val):
                    continue

                yours = indexer[var].data[j]
                if yours != val:
                    yield j

    erros = []
    for name in self.coords_to_errs:
        if name in coord_names:
            errors.extend(_find_indices_from_chaining(self.vars_to_indexers[name], name))

    return errors

def _update_context(self, context):
    context.error = list(set(context.error + self.errors))  # Append unique errors without duplicates
    for key, value in self._update_properties.items():
        if isinstance(value, dict):
            subcontext_key = _extract_subcontext_key(key)
            if subcontext_key in context:
                _update_context(context[subcontext_key], value)
            else:
                _update_context(context[subcontext_key], {})
        else:
            context[key] = value  # Append/replace values without duplicates

