class FillRequest:
    pass

class Source:
    pass

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    orcontains at least one such,
    and it is not a Source sequence.
    """
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, List):
        return any(is_fill_request_seq(subseq) for subseq in seq)
    if isinstance(seq, Source):
        return False
    raise TypeError(f"Cannot convert {type(seq)} to FillRequest or Source sequence")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq.is_filled():
        return True

    for i, item in enumerate(seq):
        if is_fill_request_seq(item):
            # More than one subsequence can lead to the end of a FillRequestSeq
            return True

    return False

