import copy

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        level = None
    if level is not None and level <= 0:
        # we reached the maximum recursion depth, refuse to go further
        return copy.deepcopy(d1)
    to_keep = set(d2.keys())
    if isinstance(d1, dict):
        res = {}
        for k in d1:
            if k in to_keep or isinstance(d1[k], (list, str, int, float)) or isinstance(d1[k], set):
                real_k = ".".join([str(d1), str(k)]) if isinstance(d1, dict) else str(d1)
                res[k] = difference(d2[k], d1[k], level=level - 1)
        if level is not None:
            for k in d1:
                if level is not None and level <= 0:
                    break
                real_k = ".".join([str(d1), str(k)]) if isinstance(d1, dict) else str(d1)
                if real_k not in to_keep:
                    res[real_k] = copy.deepcopy(d1[k])
        return res
    else:
        return d1

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """

    def _difference(subd, d1_path, d2_path, changed_level):
        diff = {}
        for k in subd:
            if k in d2:
                if isinstance(subd[k], dict) and isinstance(d2[k], dict):
                    diff.update(_difference(
                        subd[k], f"{d1_path}{k}.", f"{d2_path}{k}.", changed_level))
                elif changed_level < level and subd[k] != d2[k]:
                    diff[k] = (subd[k], d2[k])
            else:
                if changed_level < level:
                    diff[k] = (subd[k], d2_path)
        return diff

    if level < 0:
        return {k: (v, v) for k, v in d1.items() if k not in d2}

    diff = {}
    for k in d1:
        if k not in d2_PATH or k.startswith(d2_PATH):
            try:
                subd = d1[k]
            except Exception as e:
                diff[k] = (v, e)
                continue

            d1_path_len = len(d1_PATH) if d1_PATH else 0
            d2_path = subd_path if level < 0 else d2_PATH + k + '.'
            diff.update(_difference(subd, f"{d1_PATH}{k}.", f"{d2_path}{k}.", level))
    return diff

def difference(d1, d2, level=-1):
    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2}
    else:
        result = {}
        for k, v1 in d1.items():
            if k not in d2:
                result[k] = v1
            elif isinstance(v1, dict) and isinstance(d2[k], dict):
                result[k] = difference(v1, d2[k], level - 1)
        return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    from copy import deepcopy

    if level != -1 and isinstance(d1, dict) and isinstance(d2, dict):
        diff = {}
        for key in d1:
            if key not in d2:
                diff[key] = d1[key]
            elif level == 1:
                if d1[key] != d2[key]:
                    diff[key] = d1[key]
            else:
                diff[key] = difference(d1[key], d2[key], level - 1)
        return deepcopy(diff)
    else:
        return d1

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        coord = (coord,)
    if any([not isinstance(x, (int, float)) for x in coord]):
        raise TypeError("Coordinates must be numeric")

    if coord not in self.coords:
        self.coords.append(coord)
        self.values.append(weight)
        self.weights.append(weight)
    else:
        self.values[self.coords.index(coord)] += weight
        self.weights[self.coords.index(coord)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not np.isscalar(coord) and len(coord) != len(self.axes):
        raise ValueError("Coordinate must be scalar or 1D array of length equal to number of axes")

    weight = np.atleast_1d(weight)

    index = [int(np.floor(np.clip(coord[i] - self.min, 0, self.nbins - 1))) for i in range(len(coord))]
    for i in range(len(coord)):
        if index[i] == self.nbins:
            continue
        if index[i] < 0:
            continue
        self.counts[index[i]] += weight[i]

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for label_key, label_value in labels.items():
        if isinstance(label_value, list):
            for value in label_value:
                if not isinstance(value, str):
                    message = f"Improper type for label key='{label_key}', value='{value}' (should be string or bytes-like object)"
                    messages.append({'label_key': label_key, 'value': message})
        else:
            if not isinstance(label_value, str):
                message = f"Improper type for label key='{label_key}', value='{label_value}' (should be string or bytes-like object)"
                messages.append({'label_key': label_key, 'value': message})

    if messages:
        raise ValidationError(messages)

