def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match its respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for arg_name, arg_value in labels.items():
        if arg_name in '^\w+(-\w+)*$':
            try:
                jsonschema.validate(arg_value, {'type': 'string', 'regex': arg_name})
            except jsonschema.ValidationError as e:
                message = (f"Label key '{arg_name}' does not match the regex {arg_name}")
                messages.append({'arg_name': message})
        elif isinstance(arg_value, str):
            try:
                jsonschema.validate(arg_value, {'type': 'string', 'regex': arg_value})
            except jsonschema.ValidationError as e:
                message = (f"Label value '{arg_value}' does not match the regex {arg_value}")
                messages.append({'label_value': message})
        elif isinstance(arg_value, list):
            for item in arg_value:
                try:
                    jsonschema.validate(item, {'type': 'string', 'regex': item})
                except jsonschema.ValidationError as e:
                    message = (f"Item '{item}' in label value '{arg_value}' does not match the regex {item}")
                    messages.append({'item_value': message})
        else:
            message = (f"Label value '{arg_value}' does not match the regular expression for type {type(arg_value).__name__}")
            messages.append({'label_value': message})
    if messages:
        raise ValidationError(messages)

