import collections

class Model:
    SCHEMA = {}
    BASE_EXCEPTIONS = {}

def validate(cls, data):
    """Validate input data matches expected failure ``dict`` format."""
    try:
        jsonschema.validate(
            data, cls.SCHEMA,
            # See: https://github.com/Julian/jsonschema/issues/148
            types={'array': (list, tuple)})
    except jsonschema.ValidationError as e:
        raise InvalidFormat("Failure data not of the"
                                " expected format: %s" % (e.message))
    else:
        # Ensure that all 'exc_type_names' originate from one of
        # base exceptions, because those are the root exceptions that
        # python mandates/provides and anything else is invalid...
        causes = collections.deque([data])
        while causes:
            cause = causes.popleft()
            try:
                generated_on = cause['generated_on']
                ok_bases = cls.BASE_EXCEPTIONS[generated_on[0]]
            except (KeyError, IndexError):
                ok_bases = []
            root_exc_type = cause['exc_type_names'][-1]
            if root_exc_type not in ok_bases:
                raise InvalidFormat(
                    "Failure data 'exc_type_names' must"
                    " have an initial exception type that is one"
                    " of %s types: '%s' is not one of those"
                    " types" % (ok_bases, root_exc_type))
            sub_cause = cause.get('cause')
            if sub_cause is not None:
                causes.append(sub_cause)

def full_clean(self, exclude, validate_unique=False):
        """
        Validate node, on error raising ValidationErrors which can be handled by django forms

        :param exclude:
        :param validate_unique: Check if conflicting node exists in the labels indexes
        :return:
        """

        # validate against neomodel
        try:
            self.deflate(self.__properties__, self)
        except DeflateError as e:
            raise ValidationError({e.property_name: e.msg})
        except RequiredProperty as e:
            raise ValidationError({e.property_name: 'is required'})

def _ValidateArguments(arg_dict, type_check_dict):
  """Validate dictionary of arguments and return list of errors messages."""
  messages = []
  for arg_name, arg_value in arg_dict.items():
    if arg_name in type_check_dict:
      type_check = type_check_dict[arg_name]
      res = _ValidateValue(arg_value, type_check)
      if not res:
        message = ("Invalid value '%s' for argument %s. Expected %s" %
                   (arg_value, arg_name, _FormatTypeCheck(type_check)))
        messages.append(message)
  return messages

def _ValidateValue(arg_value, type_check):
  if type_check == 'string':
    return isinstance(arg_value, str)
  elif type_check == 'int':
    return isinstance(arg_value, int)
  elif type_check == 'float':
    return isinstance(arg_value, float)
  elif type_check == 'list':
    return isinstance(arg_value, list) and all(isinstance(item, type_check) for item in arg_value)
  elif type_check == 'dictionary':
    return isinstance(arg_value, dict)
  else:
    raise ValueError("Unknown type check: %s" % type_check)

def _FormatTypeCheck(type_check):
  if type_check == 'string':
    return 'str'
  elif type_check == 'int':
    return 'int'
  elif type_check == 'float':
    return 'float'
  elif type_check == 'list':
    return 'list'
  elif type_check == 'dictionary':
    return 'dict'
  else:
    raise ValueError("Unknown type check: %s" % type_check)

