import yaml

def generate_default_observer_schema(app):
    observer_schema_by_resource = {}

    for resource in app.spec.manifest:
        if resource.observer_schema is None:
            observer_schema = {}
            if 'arduino' in resource.name and resource.observer_sensor is None:
                observer_schema['arduino_setting'] = 'range=-20,20'
            if 'compartment' in resource.name and resource.observer_sensor is None:
                observer_schema['compartment_setting'] = 'range=-20,20'
            if 'usb-cable' in resource.name and resource.observer_sensor is None:
                observer_schema['usb_cable_setting'] = 'range=-20,20'
            observer_schema_by_resource[resource.name] = observer_schema

    default_observer_schema = {'resources': observer_schema_by_resource}

    return default_observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schema = {
        "order": "1",
        "type": "object",
        "properties": {}
    }
    for resource in app.spec.manifest:
        if resource.type in app.observer_schemas:
            continue
        default_resource = app.get_resource(resource.type)
        default_schema["properties"][resource.name] = {
            "order": f"{len(app.observer_schemas) + 1}",
            "type": "object",
            "properties": default_resource.observer_schema
        }
    return default_schema

def generate_default_observer_schema(app):
  """Generate the default observer schema for each Kubernetes resource present in
  ``spec.manifest`` for which a custom observer schema hasn't been specified.

  Args:
      app (krake.data.kubernetes.Application): The application for which to generate a
          default observer schema
      """
  schema = {
    'type': 'array',
    'items': {
      'type': 'object',
      'properties': {
        'kind': {
          'type': 'string'
        },
        'name': {
          'type': 'string'
        }
      },
      'required': [
        'kind',
        'name'
      ]
    }
  }
  return schema

from typing import AnyStr, Union, Dict, Tuple

class DBError(Exception):
    pass

class QueryBuilder:
    pass

class FmtParam:
    def __init__(self, value: Any, param_type: str):
        self.value = value
        self.param_type = param_type

class SQLParams:
    def __init__(self, in_style: str, out_style: str):
        self.in_style = in_style
        self.out_style = out_style

class Format:
    @staticmethod
    def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -	The formatted SQL query (:class:`str` or :class:`bytes`).

        -	The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
        """

        if isinstance(params, dict):
            if self.sql_params.in_style == 'N':
                out_params = {FmtParam(key, src_type): FmtParam(value, 'L') for key, value in params.items()}
            elif self.sql_params.in_style == 'O':
                out_params = [FmtParam(value, 'L') for value in params.values()]
        elif isinstance(params, list):
            if self.sql_params.in_style == 'N':
                out_params = [FmtParam(param, src_type) for param in params]
            elif self.sql_params.in_style == 'O':
                out_params = params
        else:
            raise ValueError("Invalid params type")

        format_sql = sql
        if self.sql_params.out_style == 'N':
            format_sql += ' (' + ', '.join(params.keys()) + ')'
        elif self.sql_params.out_style == 'O':
            format_sql += ' ' + ', '.join([f'{key} = {value}' for key, value in out_params.items()])

        return format_sql, out_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
      :class:`list`).
    """
    if isinstance(params, dict):
        result = getattrPlaceholderSQL(in_params=params)
        query = result['query']
        params = result['params']
    else:
        result = getSqlParameters(in_params=params)
        query = result['query']
        params = result['params']

    if isinstance(query, str):
        query = query.encode()

    # Perform parameter formatting based on the SQLParams.in_style setting
    if self.sqlParams.in_style == self.SQLParams.SQLITE_IN_STYLE:
        formatted_params = [self.formatSQLITEParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.POSIX_IN_STYLE:
        formatted_params = [self.formatPosixParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.ODBC_IN_STYLE:
        formatted_params = [self.formatODBCParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.SYBASE_IN_STYLE:
        formatted_params = [self.formatSYBASEParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.DERBY_IN_STYLE:
        formatted_params = [self.formatDERBYParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.MYSQL_IN_STYLE:
        formatted_params = [self.formatMYSQLParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.MSSQL_IN_STYLE:
        formatted_params = [self.formatMSSQLParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.SQLSERVER_IN_STYLE:
        formatted_params = [self.formatSQLSERVERParam(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.H2_IN_STYLE:
        formatted_params = [self.formatH2Param(p) if isinstance(p, str) else p for p in params]
    elif self.sqlParams.in_style == self.SQLParams.NOSQL_STANDARDS_IN_STYLE:
        formatted_params = [p for p in params]
    else:
        formatted_params = params

    return query, formatted_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    converted_params = {}
    cursor_insert = None
    cursor_update = None
    cursor_executemany = None

    # Check if the query is an INSERT INTO statement
    if sql.strip().upper().startswith("INSERT INTO"):
        cursor_insert = self.cursor(quote=False)
        cursor_executemany = self.cursor(quote=False, many=True)

    # Check if the query is an UPDATE statement
    elif sql.strip().upper().startswith("UPDATE"):
        cursor_update = self.cursor(quote=False)

     # Convert the in-style parameters to out-style parameters
    for i, (k, v) in enumerate(params.items()):
        if isinstance(k, (str, int)):
            converted_params[i] = v
        else:
            converted_params[k] = v

    # Execute the query with the out-style parameters
    if cursor_insert:
        cursor_insert.execute(sql, converted_params)
        result =cursor_insert.fetchall()
        cursor_insert.close()
    elif cursor_update:
        cursor_update.execute(sql, converted_params)
        cursor_update.close()
    elif sql.strip().upper().startswith("EXECUTE"):
        cursor_executemany = self.cursor(quote=False, many=True)
        cursor_executemany.execute(sql, converted_params)
        results = cursor_executemany.fetchall()
        cursor_executemany.close()

    return sql, converted_params, results

