def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ArgumentError("Inventory must be a dictionary.")

    if extract_spec_version:
        type_value = inventory.get('type', None)
        if type_value is None or not isinstance(type_value, str):
            if self.spec_version:
                type_value = self.spec_version
            else:
                raise ArgumentError("'type' is required in inventory header and must be a string.")
        try:
            version = int(type_value)
            if version not in self.supported_versions:
                raise ArgumentError(f"Unsupported type version: {version}. Supported versions are: {self.supported_versions}.")
            self.spec_version = version
        except ValueError:
            raise ArgumentError("'type' must be an integer.")

    if 'records' not in inventory:
        raise ArgumentError("Missing 'records' key in inventory.")

    records = inventory['records']
    if not isinstance(records, list):
        raise ArgumentError("'records' must be a list.")

    for item in records:
        record_type = item.get('type', None)
        if record_type is None or not isinstance(record_type, str):
            raise ArgumentError("Missing 'type' key in each record.")
        if record_type not in self.all_records:
            raise ArgumentError(f"Unsupported record type: {record_type}. Supported types are: {self.all_records}.")

        self.validate_records(item, record_type)

    if 'totals' not in inventory:
        raise ArgumentError("Missing 'totals' key in inventory.")

    totals = inventory['totals']
    if not isinstance(totals, dict):
        raise ArgumentError("'totals' must be a dictionary.")

    for key, value in totals.items():
        if key not in self.totals_fields:
            raise ArgumentError(f"Unsupported totals field: {key}. Supported fields are: {self.totals_fields}.")

        if not isinstance(value, int):
            raise ArgumentError(f"Expected integer value for totals field '{key}'. Got: {value}.")

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        if 'type' not in inventory:
            raise ValueError("'type' is required in the inventory.")
        elif not self.validators['type'].validate(inventory['type']):
            raise ValueError(f"'type' in inventory is invalid: {inventory['type']}")
    else:
        # Fallback to version-based validation if 'type' is missing or invalid
        if 'type' not in inventory:
            version = self.spec_version
