def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    path_map = {}

    for state, version_state in inventory.items():
        path_map[state] = {}

        content_files = set()
        for folder, files in version_state.items():
            for file, properties in files.items():
                if properties.get('versioned', default=True):
                    # get the full path to the file in version 'version'
                    full_path = f"{folder}/{version}/{file}"
                    if full_path not in content_files:
                        content_files.add(full_path)
                else:
                    # get the full path to the file in any version
                    full_path = f"{folder}/{file}"
                    if full_path not in content_files:
                        content_files.add(full_path)

        path_map[state] = content_files

    return path_map

