def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    directory = source if isinstance(source, str) else None
    package_folder = os.path.join(directory, source)
    if not os.path.exists(package_folder):
        os.makedirs(package_folder)

    ref_packages = {}
    for item in files:
        xml_file = os.path.join(package_folder, item)
        if os.path.isfile(xml_file):
            xml_filename, root = extract_root_from_xml(xml_file, simplify=False, add_key=False)
            try:
                if xml_filename not in ref_packages:
                    ref_packages[xml_filename] = {
                        "type": "package",
                        "root": root
                    }
                else:
                    ref_packages[xml_filename]["root"] = root
            except Exception as e:
                print(f"Error processing {xml_file}: {e}")

    return ref_packages

