    from xml.etree import ElementTree as ET
    import os

    # Get all xml files in the folder
    xml_files = [f for f in os.listdir(folder) if f.endswith('.xml')]

    # Group files by their XML basename
    grouped_files = {}
    for file in xml_files:
        basename = os.path.splitext(file)[0]
        if basename not in grouped_files:
            grouped_files[basename] = []
        grouped_files[basename].append(
            os.path.join(folder, file))

    # Parse each XML file and get data
    data = []
    for files in grouped_files.values():
        tree = ET.parse(files[0])
        root = tree.getroot()
        category = root.find('category').text
        data.append(
            {
                'filename': files[0],
                'category': category
                }
        )

    return data

