def _extract_number_and_suppl_from_issue_element(issue):
    import re
    output = ""
    pattern = r"[0-9\-\s]+"
    matches = re.findall(pattern, issue)
    for match in matches:
        if match.startswith('spec'):
            output += f"{match} "
        else:
            output += f"{match} "
    return output.strip()

