def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

            A & (A | B) = A, A | (A & B) = A

    Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
    """""
    result = []
    for expr in args:
        if expr == "A":
            result.append("A")
        elif expr == "B":
            result.append("B")
        elif expr == "A|B":
            result.append("A|B")
        elif expr == "A&B":
            result.append("A&B")
        elif expr == "A^B":
            result.append("A^B")
        elif expr == "A|~B":
            result.append("A|~B")
        elif expr == "A&~B":
            result.append("A&~B")
    return result

def absorb(self, args):
    absorbing_exprs = []
    neg_absorbing_exprs = []
    for param in args:
        if param.startswith('~'):
            absorbing_exprs.append(param[1:])
        else:
            neg_absorbing_exprs.append(param)
    for expr in absorbing_exprs:
        matched = any(expr.startswith(c) for c in neg_absorbing_exprs)
        if matched:
            return True
    return False

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
        """
    absorbed = []
    negative_absorbed = []

    for arg in args:
        # Check for absorption
        if ' & ' in arg and '|' in arg:
            # Split the arguments
            parts = arg.split(' & ')
            for part in parts[1:]:
                if '|' in part:
                    # Split the parts even further and check for absorption
                    if ' & ' in part and '|' in part:
                        absorbed.append(arg)
                    else:
                        negative_absorbed.append(arg)
                else:
                    absorbed.append(arg)
        # Check for negative absorption
        elif ' & ' in arg and '~' in arg:
            if '|' in arg:
                # Split the arguments and check for negative absorption
                parts = arg.split(' & ')
                for part in parts[1:]:
                    if '|' in part:
                        # Split the parts and check for negative absorption
                        if ' & ' in part and '~' in part:
                            absorbed.append(arg)
                        else:
                            negative_absorbed.append(arg)
                    else:
                        absorbed.append(arg)
            else:
                negative_absorbed.append(arg)
        else:
            absorbed.append(arg)

    return absorbed, negative_absorbed

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
        """
    absorption_list = []
    negative_absorption_list = []
    for arg in args:
        if '|' in arg:
            left, right = arg.split('|')
            if '&' in left and '&' in right:
                left = left.split('&')
                right = right.split('&')
                if left[0] == right[0]:
                    absorption_list.append(arg)
                elif left[1] == right[1]:
                    absorption_list.append(arg)
            elif '|' in left and '~' in right:
                absorption_list.append(arg)
            elif '|' in right and '~' in left:
                absorption_list.append(arg)
        elif '&' in arg:
            left, right = arg.split('&')
            if '~' not in left and '~' not in right:
                if left == right:
                    absorption_list.append(arg)
                elif left != right:
                    negative_absorption_list.append(arg)
    return absorption_list, negative_absorption_list

