def next_version(version):
    if not version:
        return "0.1.0"

    match = re.match(r'(0*)(\d+)\.(\d+)\.(\d+)', version)
    if not match:
        raise ValueError("Invalid version format")

    release, major, minor = match.groups()

    # Increment major if it's zero-prefixed
    if major == '0':
        major = str(int(major) + 1)
    else:
        major = str(int(major) + 1)

    return f"{release}{major}.{minor}.{int(minor) + 1}"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate each version directory exists
    for version_dir in version_dirs:
        if not os.path.exists(version_dir):
            raise FileNotFoundError(f"Version directory '{version_dir}' does not exist.")
        # Check if the version directory contains an inventory
        inventory_file = os.path.join(version_dir, 'inventory.yaml')
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"Inventory file not found in version directory '{version_dir}'.")
        # Load the inventory yaml
        with open(inventory_file, 'r') as f:
            inventory = yaml.safe_load(f)
            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory file in version directory '{version_dir}' is not a dictionary.")
            if 'content_signatures' not in inventory:
                raise KeyError(f"Content signatures not found in version directory '{version_dir}' inventory.")

    # Create a mapping of content signatures to files
    content_signatures = {}
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.yaml')
        with open(inventory_file, 'r') as f:
            inventory = yaml.safe_load(f)
            for path, signature in inventory['content_signatures'].items():
                content_signatures[signature] = path

    # Load the root inventory
    root_inventory_file = os.path.join(version_dirs[0], 'inventory.yaml')
    with open(root_inventory_file, 'r') as f:
        root_inventory = yaml.safe_load(f)
        if not isinstance(root_inventory, dict):
            raise ValueError(f"Root inventory file is not a dictionary.")
        if 'content_signatures' not in root_inventory:
            raise KeyError(f"Content signatures not found in root inventory.")

    # Compare content signatures in each version with the root inventory
    for signature, path in root_inventory['content_signatures'].items():
        # Check if the signature is present in the current version
        if signature not in content_signatures:
            raise ValueError(f"Content signature '{signature}' not found in any version directory.")
        # Check if the paths match
        if content_signatures[signature] != path:
            raise ValueError(f"Content signature '{signature}' found in version directory {os.path.dirname(path)} but not matching the root inventory.")

    # Verifying that each version has an inventory up to that point
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.yaml')
        with open(inventory_file, 'r') as f:
            inventory = yaml.safe_load(f)
            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory file in version directory '{version_dir}' is not a dictionary.")
            if 'current_version' in inventory:
                if int(inventory['current_version']) != len(version_dirs):
                    raise ValueError(f"Version directory index '{int(inventory['current_version'])}' does not correspond to the version sequence.")

