def find_path_type(path):
    if not path.startswith("0=*"):
        return "not root; probably not an OCFL Storage Root"
    if not path.endswith("/"):
        return "not object; probably not an OCFL Object"
    inventory_path, _ = path.rsplit("/", 1)
    if not inventory_path:
        return "root; but lacks a file path"
    if not os.path.exists(inventory_path):
        return "root; but the associated file does not exist"
    if not os.path.isfile(inventory_path):
        return "root; but the associated file is not a file"
    return "file; the associated file is an inventory"

