class Bugsy:
    def __init__(self, username, password):
        self._username = username
        self._password = password
        self._have_auth = False

    def _get_auth(self):
        auth = (self._username, self._password)
        return auth

    def request(self, endpoint, method, **kwargs):
        headers = {
            "Content-Type": "application/json",
            "Authorization": f"Basic {self._get_auth()}",
        }
        try:
            response = requests.request(
                method, f"https://bugzilla.example.com/{endpoint}", headers=headers, json=kwargs
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            raise BugsyException(f"An error occurred while making the request: {e}")

    def get(self, bug_id):
        result = self.request(f"bug/{bug_id}")
        return Bug(
            id=result["bugs"][0]["id"],
            summary=result["bugs"][0]["summary"],
            status=result["bugs"][0]["status"],
            comment=result["bugs"][0]["comment"]
        )

    def put(self, bug):
        if not self._have_auth:
            raise BugsyException("Unfortunately you can't put bugs in Bugzilla"
                                 " without credentials")

        if not isinstance(bug, Bug):
            raise BugsyException("Please pass in a Bug object when posting"
                                 " to Bugzilla")

        if not bug.id:
            result = self.request('bug', 'POST', json=bug.to_dict())
            if 'error' not in result:
                bug._bug['id'] = result['id']
                bug._bugsy = self
                try:
                    bug._bug.pop('comment')
                except Exception:
                    # If we don't have a `comment` we will error so let's just
                    # swallow it.
                    pass
            else:
                raise BugsyException(result['message'])
        else:
            result = self.request('bug/%s' % bug.id, 'PUT',
                                  json=bug.to_dict())
            updated_bug = self.get(bug.id)
            return updated_bug

    def update(self, **kwargs):
        """Update `params` values using alias.
        """
        for k in self.prior_params:
            try:
                self.params[k] = kwargs[self.alias[k]]
            except(KeyError):
                pass

    def amend_bzparams(self, params, bug_ids, alias):
        """Amend the Bugzilla params"""

        for bug_id in bug_ids:
            bug = self.get(bug_id)
            for param in params:
                if param in alias:
                    setattr(bug, param, alias[param])
                else:
                    setattr(bug, param, params[param])
            self.put(bug)

