from typing import List, Tuple

class Node:
    def __init__(self, value):
        self.value = value
        self.links = {}

    def add_link(self, target, weight):
        self.links[target] = weight

    def merge_links_from(self, other_node):
        for other_link in other_node.links:
            for existing_link in self.links:
                if existing_link.value == other_link.value:
                    existing_link.weight += other_link.weight
                    break
            else:
                self.add_link(other_link.key, other_link.weight)

def deep_merge_nodes(nodes: List[Tuple[Node, Node]]) -> List[Tuple[Node, Node]]:
    merged_nodes = []
    value_map = {}

    for node_a, node_b in nodes:
        if node_a.value not in value_map:
            value_map[node_a.value] = [node_a]
        else:
            value_map[node_a.value].append(node_a)

        if node_b.value not in value_map:
            value_map[node_b.value] = [node_b]
        else:
            value_map[node_b.value].append(node_b)

    for value, nodes in value_map.items():
        if len(nodes) > 1:
            merged_nodes.append((nodes[0], nodes[0]))
            for node in nodes[1:]:
                node.merge_links_from(nodes[0])
        else:
            merged_nodes.append((nodes[0], nodes[0]))

    return merged_nodes

