def deep_merge_nodes(nodes):
    def _merge_values(node1, node2):
        if isinstance(node1, dict) and isinstance(node2, dict):
            merged = {}
            for key in node1:
                merged[key] = _merge_values(node1[key], node2.get(key, None))
            for key in node2:
                if key not in merged:
                    merged[key] = _merge_values(node2[key], None)
            return merged
        elif isinstance(node1, (int, str)) and isinstance(node2, (int, str)):
            return node2 if node1 == node2 else node1 if node1 else node2
        else:
            return None

    merged_nodes = []
    key_counts = {}
    for node in nodes:
        key = node[0].value
        value = node[1]
        if key in key_counts:
            existing_value = merged_nodes[key_counts[key]].[1]
            new_value = _merge_values(existing_value, value)
            if new_value is not None:
                merged_nodes[key_counts[key]][1] = new_value
        else:
            merged_nodes.append([node[0], value])
            key_counts[key] = len(merged_nodes) - 1

    return [(k, v[1]) for k, v in enumerate(merged_nodes)]

