def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # check if the url and url_args are not empty and Url_args is not None
    if not url or not url_args or url_args is None:
        return None

    # replace all custom string URL items in the url with the corresponding values from url_args
    for key, value in url_args.items():
        url = url.replace('{'+ key + '}', value)

    # return the modified url
    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    parsed_url = urllib.parse.urlparse(url)
    query_params = urllib.parse.parse_qs(parsed_url.query)

    for key, value in url_args.items():
        query_params[key] = value

    updated_query = urllib.parse.urlencode(query_params, doseq=True)
    new_parts = parsed_url._replace(query=updated_query)
    return urllib.parse.urlunparse(new_parts)

