def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    if len(vertices) < 3:
        raise ValueError("Input poly should have at least 3 vertices")
    sides = (vertices[1:] + vertices[:1])
    return tuple((vertices[i], side) for i, side in enumerate(sides))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding =0
    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    if padding:
        digits += alphabet * (padding - len(digits))
    return ''.join(reversed(digits))

from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if number == 0:
        return "0"
    if padding is None:
        padding = 0
    result = ""
    n, base = number, len(alphabet)
    while n > 0:
        result = alphabet[n % base] + result
        n //= base
    while len(result) < padding:
        result = alphabet[0] + result
    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        # Handle negative numbers by converting to positive and then appending the '-' sign
        return '-' + int_to_string(-number, alphabet, padding=padding)
    if padding is not None:
        # Ensure the number is at least as long as the padding length by adding padding characters
        number_str = str(number)
        if len(number_str) < padding:
            number_str = number_str.lzfill(padding)
    else:
        number_str = str(number)
    # Convert each digit of the number to its corresponding character in the alphabet
    digits = [alphabet[digit] for digit in number_str]
    return ''.join(digits)

def int_to_string(number, alphabet, padding=None):
    number_custom = []
    if padding is None: padding = 0

    while number > 0:
        number_custom.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    missing不够 = padding - len(number_custom)
    number_custom = number_custom + missing不够*[alphabet[0]]
    number_custom.reverse()

    return "".join(number_custom)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""

    if not isinstance(value, str):
        raise ValueError("value must be a string")

    result = value.replace('.', arg)

    if not isinstance(result, str):
        raise ValueError("replacement failed")

    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.add(c)

    seen.remove(cls)
    return seen

