from typing import List, Any

def string_to_int(string: str, alphabet: List[str]) -> int:
    # Initialize the result to 0
    result = 0

    # Reverse the string to process digits from the least significant to the most significant
    string = string[::-1]

    # Create a dictionary to map characters in the alphabet to their corresponding values
    char_dict = {char: index for index, char in enumerate(alphabet)}

    # Iterate over each character in the string
    for i, char in enumerate(string):
        if char in char_dict:
            power = i  # The power of the base is the position of the character
            result += power * char_dict[char]  # Add the character's value to the result
        else:
            raise ValueError(f"Invalid character '{char}' in the alphabet mapping")

    return result

