def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\', '\\').replace('"', '"')
        if name.startswith('<') and name.endswith('>'):
            return name[1:-1].replace('<', '').replace('>', '')
    return name

def unquote(name: str) -> str:
    """Remove quote from the given name."""
    if name != name.strip():
        raise ValueError(f"Name must not contain leading or trailing spaces")
    if len(name) > 1:
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\\\', '\\').replace('\\"', '"')
    return name

