def split(s, platform=default_platform):
    if platform == 'this':
        platform = default_platform

    if platform == POSIX:
        pattern = '"([^"]+)|"([^"]+)"|([^\s"]+)\s+([^\s"]+)'
        return re.findall(pattern, s)

    elif platform == Windows_CMD:
        pattern = '"([^"]+)|"([^"]+)"|([^" ]+) ""([^" ]+)'
        return re.findall(pattern, s)

    else:
        raise ValueError("Invalid platform specified")

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = platform_system()
    elif platform == 0:
        platform = 'cmd'
    else:
        assert platform == 1, "Invalid platform value"

    # Windows/CMD requires quoting to avoid removing quotes around arguments
    if platform == 'cmd':
        result = re.sub(r'"([^"]+)"', r'"$1"', s)
    else:
        result = re.sub(r'"([^"]+)"|\'([^']+)\'', r'$1$2', s)

    # Split by quotes or spaces
    parts = re.split(r'(\s+|"[^"]+"|\'[^\']+\')', result)

    # Remove empty strings
    parts = [part for part in parts if part]

    return parts

