    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    num = re.findall(r'\d+', frequency)[0]
    unit = frequency.lower().split()[-1]

    if unit == "weeks":
        return datetime.timedelta(weeks=int(num))
    elif unit == "days":
        return datetime.timedelta(days=int(num))
    elif unit == "months":
        return datetime.timedelta(days=int(num) * 30)
    elif unit == "years":
        return datetime.timedelta(days=int(num) * 365)
    else:
        raise ValueError("Invalid frequency unit")

def parse_frequency(frequency):
    ''' Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency == "always":
        return None
    m = re.match(r'(.*?)(\d+)', frequency)
    if not m:
        raise ValueError("Invalid frequency format")
    unit = m.group(1)
    if unit not in ["seconds", "minutes", "hours", "days", "weeks"]:
        raise ValueError("Invalid unit of time")
    if unit == "seconds":
        factor = 1
    elif unit == "minutes":
        factor = 60
    elif unit == "hours":
        factor = 3600
    elif unit == "days":
        factor = 86400
    elif unit == "weeks":
        factor = 86400 * 7
    try:
        value = int(m.group(2))
        return datetime.timedelta(seconds=value * factor)
    except ValueError:
        raise ValueError("Invalid value for frequency")

