import re

def make_find_paths(find_paths):
    result = []
    for path in find_paths:
        if path.count('.') == 0:
            # it's a pattern
            result.append(path)
        else:
            if path.endswith('/name'):
                result.append('sh:' + re.escape(path[:-7]) + '**/*name*/**')
            else:
                result.append('sh:' + re.escape(path) + '**/*')
    return result

