def write_configuration(self, config_filename, rendered_config, mode=0o600, overwrite=False):
    """Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    if not overwrite and os.path.isfile(config_filename):
        return
    else:
        try:
            config_path_dir_name = os.path.dirname(config_filename)
            os.makedirs(config_path_dir_name)
        except OSError:
            if not os.path.isdir(config_path_dir_name):
                raise
        fh = open(config_filename, 'wb')
        try:
            fh.write(rendered_config)
            fh.close()
        except IOError as e:
            os.remove(config_filename)
            fh.close()
            raise

def write_configuration(self, config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    config_path = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_path):
        return
    else:
        try:
            os.makedirs(os.path.dirname(config_path), exist_ok=True)
        except OSError:
            if not os.path.isdir(os.path.dirname(config_path)):
                raise
        with open(config_path, "w") as f:
            f.write(rendered_config)
            f.close()

from typing import *

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if 'name' not in matcher:
        raise KeyError("Matcher contains no 'name' field.")
    name = matcher['name']
    if 'default' in matcher:
        default = matcher['default']
    else:
        default = None
    if name not in os.environ:
        if default is not None:
            return default
        raise EnvironmentError(f"Environment variable '{name}' not found.")
    return os.environ[name]

def _parse_image_ref(image_href):
    if not image_href.startswith("http://"):
        image_href = "http://" + image_href
    url = urllib.parse.urlparse(image_href)
    if url.scheme == "http" or url.scheme == "https":
        use_ssl = True
    else:
        use_ssl = False

    return url.path.split("?", 1)[0], url.netloc, use_ssl

