    """

    if strip:
        pattern = re.sub(r'\W+', '', pattern)  # Remove non-word characters

    if not isinstance(pattern, str):
        raise TypeError("Non-string pattern provided")

    pattern = re.escape(pattern)  # Escape special characters

    return pattern

