def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if graph is None or prop is None:
        raise ValueError("Graph and property must not be None")

    if not isinstance(graph, Graph):
        raise TypeError("graph must be of type 'Graph'")

    if not isinstance(prop, URIRef):
        raise TypeError("prop must be of type 'URIRef'")

    if roots is None:
        roots = set()

    todo = deque()
    visited = set()
    new_roots = set()

    for node in graph.nodes():
        if node not in visited:
            todo.append(node)
            visited.add(node)

    while todo:
        current_node = todo.popleft()
        if current_node not in visited or current_node in roots:
            continue
        if graph._predicate_to_object.get((current_node, prop)) is None:
            new_roots.add(current_node)
        else:
            for other_node in graph.successors(current_node):
                if other_node not in visited:
                    todo.append(other_node)
                    visited.add(other_node)

    return roots.union(new_roots)

from rdflib import Graph, URIRef

from typing import Set, Optional

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()
    todo = set(graph.subjects(pred=prop))
    done = set()

    while True:
        if todo:
            node = todo.pop()
        elif not graph.subjects(pred=prop):
            break
        if node in done:
            continue

        parents = set(graph.predecessors(node))
        if not parents:
            roots.add(node)
            continue

        more_todo = parents - done - roots
        if not more_todo:
            break
        todo.update(more_todo)
        continue

    return roots

