from typing import Optional, Set

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    subjects = graph.subjects(prop)
    for subject in subjects:
        if subject not in roots:
            parents = graph.objects(subject)
            if not parents:
                roots.add(subject)
            else:
                for parent in parents:
                    find_roots(graph, prop, roots)

    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    root_set = set()
    parent_to_child = {}
    s = graph.subjects(predicate=prop)
    for node in s:
        parent_to_child[node] = set()

    s = graph.objects(predicate=prop)
    for node in s:
        parent_to_child[parent_to_child[node]].add(node)

    if not roots:
        for key in parent_to_child:
            if key not in parent_to_child[parent_to_child[key]]:
                root_set.add(key)
    else:
        root_set = roots

    return root_set

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    roots = set() if roots is None else roots
    stack = []

    for subject in graph.subjects(property=prop):
        if subject not in roots:
            stack.append(subject)

    while stack:
        root = stack.pop()
        if root not in roots:
            roots.add(root)
            for object_ in graph.objects(subject=subject, predicate=prop):
                if object_ not in roots:
                    stack.append(object_)

    return roots

