import logging

from typing import List, Optional, Tuple

def load_configurations(config_filenames: List[str], overrides: Optional[dict] = None, resolve_env: bool = True) -> Tuple[dict, List[logging.LogRecord]]:
    results = {}
    errors = []

    try:
        for filename in config_filenames:
            log = logging.getLogger(filename)

            raw_config = f'loading {filename}'
            log.info(raw_config)

            if resolve_env:
                resolve_config(filename, overrides, log)

            parsed_config = parse_configurations(filename, overrides, log)

            log.debug(f'Parsed config for {filename}: {parsed_config}')
            results[filename] = parsed_config

    except Exception as e:
        log.error(f'Failed to parse {filename}: {e}')
        errors.append(logging.LogRecord(f'FailedParser:{filename}', logging.ERROR, None, None, str(e), None, None))

    return results, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    def validate(config:
        """Validate config values.

        :raise HandledError: On invalid config values.

        :param dict config: Dictionary from get_arguments().
        :param logging.Logger log: Logger for this function. Populated by with_log() decorator.
        """
        if config['always_job_dirs'] and config['no_job_dirs']:
            log.error('Contradiction: --always-job-dirs and --no-job-dirs used.')
            raise HandledError
        if config['commit'] and not REGEX_COMMIT.match(config['commit']):
            log.error('No or invalid git commit obtained.')
            raise HandledError
        if config['dir'] and not os.path.isdir(config['dir']):
            log.error("Not a directory or doesn't exist: %s", config['dir'])
            raise HandledError
        if config['no_job_dirs'] not in ('', 'rename', 'overwrite', 'skip'):
            log.error('--no-job-dirs has invalid value. Check --help for valid values.')
            raise HandledError
        if not config['owner'] or not REGEX_GENERAL.match(config['owner']):
            log.error('No or invalid repo owner name obtained.')
            raise HandledError
        if config['pull_request'] and not config['pull_request'].isdigit():
            log.error('--pull-request is not a digit.')
            raise HandledError
        if not config['repo'] or not REGEX_GENERAL.match(config['repo']):
            log.error('No or invalid repo name obtained.')
            raise HandledError
        if config['tag'] and not REGEX_GENERAL.match(config['tag']):
            log.error('Invalid git tag obtained.')
            raise HandledError

    results = []
    parse_errors = []
    logger = logging.getLogger(__name__)

    for config_filename in config_filenames:
        try:
            log_config = toml.load(config_filename) if config_filename.endswith('.toml') else yaml.safe_load(open(config_filename))
            validate(log_config)
            results.append((config_filename, log_config))
        except ParseError as e:
            parse_errors.append((config_filename, str(e)))
            logger.error("Failed to parse configuration file: %s", config_filename)

    return results, parse_errors

