        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if tentative:
        iface.providedBy(candidate)
    else:
        try:
            iface.providedBy(candidate)
        except zope.interface.Invalid as e:
            raise zope.interface.Invalid("Candidate does not provide interface %s" % (iface,))
    candidate.implementedBy(iface)
    candidate.providedBy(iface)
    candidate.__parent__ = iface
    methods = set()
    attributes = set()
    for name, attr in candidate.__dict__.items():
        if inspect.ismethod(attr):
            methods.add(name)
        elif inspect.isfunction(attr):
            methods.add(name)
        elif name.islower() and name[0].isupper():
            attributes.add(name)
    for method in methods:
