    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    if tentative:
        if iface.providedBy(candidate) is False:
            raise SiriusError("Candidate does not provide the interface %s" % iface)
        return True
    if not iface.providedBy(candidate):
        raise SiriusError("Candidate does not provide the interface %s" % iface)
    candidate_interface = iface(discriminator=candidate)
    if interface is not candidate_interface and\
       candidate_interface is not iface(discriminator=iface):
        raise SiriusError("Candidate is not a substitute for the interface %s" % iface)
    return True

def _TypecheckFunction(function, args, positional_arguments, keyword_arguments):
    error_messages = []
    params = inspect.signature(function).parameters
    # check if the function has positional arguments
    for i, arg in enumerate(positional_arguments):
        if arg not in params:
            error_messages.append(f"Positional argument {i+1} is not valid")
    # check if the function has keyword arguments
    for keyword, value in keyword_arguments.items():
        if keyword not in params:
            error_messages.append(f"Keyword argument {keyword} is not valid")
    # check if the function has all necessary parameters
    for param, spec in params.items():
        if spec.kind == inspect.Parameter.POSITIONAL_ONLY and param not in positional_arguments:
            error_messages.append(f"Parameter {param} is not provided")
        elif spec.kind == inspect.Parameter.POSITIONAL_OR_KEYWORD and param not in args and param not in positional_arguments:
            error_messages.append(f"Parameter {param} is not provided")
        elif spec.kind == inspect.Parameter.KEYWORD_ONLY and param not in keyword_arguments:
            error_messages.append(f"Parameter {param} is not provided")
        elif spec.kind == inspect.Parameter.VAR_POSITIONAL and param not in args:
            error_messages.append(f"Parameter {param} is not provided")
        elif spec.kind == inspect.Parameter.VAR_KEYWORD and param not in keyword_arguments:
            error_messages.append(f"Parameter {param} is not provided")
    if error_messages:
        raise ValueError("; ".join(error_messages))
    return function

