class VerifyObject(object):
    def __init__(self, nominee):
        self.nominee = nominee

    def verifyObject(self, iface, candidate, tentative=False):
        if tentative:
            if inspect.isclass(self.nominee) and \
               issubclass(self.nominee, iface) or \
               hasattr(self.nominee, 'implements') and \
               iface.providedBy(self.nominee):
                return True
            elif isinstance(self.nominee, callable) and \
               inspect.isfunction(self.nominee) or \
               inspect.ismethod(self.nominee) or \
               hasattr(self.nominee, 'provider') and \
               iface.providedBy(self.nominee):
                return True
            elif isinstance(self.nominee, (list, tuple)):
                return self._verifyObjectList(iface, candidate, tentative)
            elif isinstance(self.nominee, Interface):
                return self._verifyInterface(iface, candidate, tentative)
            else:
                return False
        else:
            if not inspect.isclass(self.nominee) and \
               issubclass(self.nominee, iface) or \
               hasattr(self.nominee, 'implements') and \
               iface.providedBy(self.nominee):
                return True
            elif isinstance(self.nominee, callable) and \
               inspect.isfunction(self.nominee) or \
               inspect.ismethod(self.nominee) or \
               hasattr(self.nominee, 'provider') and \
               iface.providedBy(self.nominee):
                return True
            elif isinstance(self.nominee, (list, tuple)):
                return self._verifyObjectList(iface, candidate, tentative)
            elif isinstance(self.nominee, Interface):
                return self._verifyInterface(iface, candidate, tentative)
            else:
                return False

    def _verifyObjectList(self, iface, candidate, tentative):
        for item in candidate:
            if not self.verifyObject(iface, item, tentative):
                return False
        return True

    def _verifyInterface(self, iface, candidate, tentative):
        methods = iface.getMethods()
        for name, method in methods.items():
            if not hasattr(candidate, name):
                raise Invalid(f"Method {name} not found in candidate")
            elif getattr(candidate, name).__code__ != method.__code__:
                raise Invalid(f"Method {name} signature does not match")
            elif not hasproperty(candidate, name):
                raise Invalid(f"Method {name} is not a property")
        for attr_name in iface.getAttributes():
            if not hasattr(candidate, attr_name):
                raise Invalid(f"Attribute {attr_name} not found in candidate")
            elif getattr(candidate, attr_name).__code__ != getattr(iface, attr_name).__code__:
                raise Invalid(f"Attribute {attr_name} signature does not match")
        return True

