class ParserError(Exception):
    pass

def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")

    if tzinfos is None:
        tzinfos = {}

    try:
        parsed = self._parse(timestr, kwargs, timezone)
    except ValueError as e:
        if default is not None and isinstance(default, datetime):
            return self._parse(str(default), kwargs, timezone)
        else:
            raise e

    if ignoretz:
        return parsed.replace(tzinfo=None)

    # Convert to timezone in tzinfos
    if not isinstance(tzinfos, dict):
        tzinfos = {tzname: gettz(tzname) for tzname in tzinfos}

    for tzname, tzinfo in tzinfos.items():
        if isinstance(tzinfo, int):
            tzinfo = timezone(timedelta(seconds=tzinfo))
        if isinstance(tzinfo, timezone):
            return parsed.astimezone(tzinfo)

    raise ValueError("unknown timezone")

