import re

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tag_expr = re.compile(r"^\s*tag: (.*?)\s*$", re.IGNORECASE)
    tags = set()
    text_parts = text.split("\n")
    for i in range(len(text_parts)):
        try:
            part = text_parts[i].strip()
            if part:
                match = tag_expr.match(part)
                if match:
                    tag = match.group(1)
                    tags.add(tag)
                    if replacer:
                        text_parts[i] = text_parts[i].replace("tag:", replacer(tag)).strip()
        except IndexError:
            pass

    return tags, "\n".join(text_parts)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    lines = text.split('\n')
    new_text = ''

    for line in lines:
        if line.strip().startswith(':'):
            continue  # Ignore lines starting with ':'
        elif line.strip().startswith('from .. import'):
            continue  # Ignore lines starting with 'from .. import'

        if line.strip():
            tags.update(re.findall(r'\b\w+\b', line))

        if replacer:
            new_text += replacer(line) + '\n'
        else:
            new_text += line + '\n'

    return tags, new_text

