        value = memoized_urls.get(m.group(0), _NO_URL)
        if value is _NO_URL:
            value = to_url(m)
            memoized_urls[m.group(0)] = value
        return value

    def to_url(m):
        if m.group(1):
            return m.group(0)  # It's an http(s) url.
        path = m.group(0)

        if path.startswith('/'):
            path = os.path.relpath(path, buildroot)
        elif path.startswith('..'):
            # The path is not located inside the buildroot, so it's definitely not a BUILD file.
            return None
        else:
            # The path is located in the buildroot: see if it's a reference to a target in a BUILD file.
            parts = path.split(':')
            if len(parts) == 2:
                putative_dir = parts[0]
            else:
                putative_dir = path
            if os.path.isdir(os.path.join(buildroot, putative_dir)):
                build_files = list(BuildFile.get_build_files_family(
                  FileSystemProjectTree(buildroot),
                  putative_dir))
                if build_files:
                    path = build_files[0].relpath
                else:
                    return None

        if os.path.exists(os.path.join(buildroot, path)):
            # The reporting server serves file content at /browse/<path_from_buildroot>.
            return '/browse/{}'.format(path)
        else:
            return None

    def maybe_add_link(url, text):
        return '<a target="_blank" href="{}">{}</a>'.format(url, text) if url else text

    def process_links(text):
        url_regex = re.compile('(\[([^\]]+)\]\(([^)]+)\)')
        url_regex_sub = re.compile(r'\[\]\(([^)]+)\)')

        while url_regex_search:
            match = url_regex_search.group(0)
            url_text = match[1]
            url_path = match[2]

            url = memoized_to_url(url_search)
            if url:
                text = text[:url_regex_search.start()] + maybe_add_link(url, url_text) + text[url_search.end():]
            url_regex_search = url_regex.search(text)

        return url_regex_sub.sub(lambda m: ' ' + m.group(0)[1:-1], text)

    memoized_urls = {}
    text = process_links(text)
    return text

def process_text_links(text):
  """Process links in text, adding some attributes and linkifying textual links."""

  link_attrs = getattr(sys.modules['libmarkdown'], '_link_attrs_func')
  def add_attrs(url, text, attrs=None):
    attrs = attrs or {'target': '_blank'}
    return '<a href="{}"{}>{}</a>'.format(url, ' '.join(['id="{}"'.format(a) for a in attrs.keys()]), text)

  text.replace('http://www.example.com', add_attrs('http://www.example.com', 'example.com'))
  text.replace('https://www.example.com', add_attrs('https://www.example.com', 'example.com'))
  text.replace('file:///path/to/file', add_attrs('file:///path/to/file', 'file:///path/to/file'))
