import urllib.request

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""

    if not url:
        return None

    req = urllib.request.HeadRequest(url, headers={'Host': urllib.request.urlparse(url).netloc})
    resp = urllib.request.urlopen(req)
    try:
        if resp.code != 200 or resp.info().getContentType() == 'text/plain':
            return None
        return resp.info().getContentType()
    finally:
        resp.close()

