def verify_relayable_signature(public_key, doc, signature):
    """ Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Validate the signature using the given public key
    try:
        return xml.etree.ElementTree.XML(doc).find(".//{http://www.w3.org/2000/xmlns/xmldsig}Signature").signature.assertValid(public_key) == True
    except (xml.etree.ElementTree.SignatureError, xml.etree.ElementTree.ParserError):
        return False

