def parse_diaspora_webfinger(document: str) -> Dict:
    root = fromstring(document)
    results = {}

    if root.tag == "xrd":  # Old format
        for link in root.findall(".//{http://www.w3.org/2008/wapi/webfinger}link[@rel='http://www.w3.org/2008/wapi/webfinger#me']/@href"):
            results["site"] = link.text

            for localized in root.findall(".//{http://www.w3.org/2008/wapi/webfinger}link[@rel='http://diaspora.org/xrd/{0}/localized']".format(link.text)):
                results[localized.attrib.get("lang", "en")] = localized.text

    elif root.tag == "jsonld":  # New format
        uuid = root.find("http://schema.org/Person/uuid").text
        results = {"uuid": uuid}

        for webpage in root.findall(".//http://schema.org/WebPage"):
            for url in webpage.findall("./http://schema.org/url"):
                results["hcard_url"] = url.text
                break
        break

    elif root.tag == "book":
        results = {
            "uuid": root.find("http://schema.org/Book/uuid").text,
            "title": root.find("http://schema.org/Book/title").text,
            "author": [
                author.get("name")
                for author in root.findall(".//http://schema.org/Book/author")
            ],
            "isbn": root.find("http://schema.org/Book/isbn").text,
            "publisher": root.find("http://schema.org/Book/publisher").text,
            "publishedDate": root.find("http://schema.org/Book/publishedDate").text,
        }

    return results

