def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    groups = {}
    for spec in self._global_elements_spec:
        if spec.get('directive') == 'include_groups':
            included_group = spec['include_groups']
            if included_group in groups:
                raise ValueError(f"Duplicate include groups: {included_group}")
            groups[included_group] = {k: v for k, v in self._global_elements_spec.items() if v['include_groups'] == included_group}
    for group in self._global_elements_spec.values():
        if group.get('include_groups') is not None:
            raise ValueError(f"Group {group['group_name']} includes itself: {group['include_groups']}")
    self._global_elements_spec = {k: v for k, v in self._global_elements_spec.items() if v['include_groups'] is None or v['include_groups'] not in groups}
    for group_name, included_group in groups.items():
        if len(included_group) > 0:
            parser_dict.update(included_group)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    from typing import Any, Dict, Union

    def parse_dict(payload: Any) -> Dict[str, Any]:
        if isinstance(payload, dict):
            parsed = {}
            for key, value in payload.items():
                if key == 'condition':
                    condition = parse_dict(value)
                    if not condition:
                        continue
                else:
                    parsed[key] = parse_dict(value)
            return parsed
        return payload

    include_directive_count = 0

    for section, payload in parser_dict.items():
        if section == 'include':
            include_directive_count += 1
            parsed = parse_dict(payload)
            group_name = parsed.get('name')
            if not group_name:
                raise ValueError(f"Missing 'name' field in 'include' directive: {payload}")
        else:
            raise ValueError(f"Invalid directive: {self.parser_name}.{section}")

    if include_directive_count == 0:
        raise ValueError(f"No 'include' directive found in {self.parser_name}")

    return parser_dict

