    deprecated_map = {
        'arg1': 'new_arg1',
        'arg2': 'new_arg2',
    }
    warnings.filterwarnings('always', category=DeprecationWarning, module=__name__)
    for old, new in deprecated_map.items():
        if old in cli_args:
            warnings.warn(
                f"'{old}' is deprecated in favour of '{new}'. '{old}' will be removed in a future version.",
                category=DeprecationWarning,
                stacklevel=2,
            )
            cli_args[new] = cli_args.pop(old)
    warnings.filterwarnings('default', category=DeprecationWarning, module=__name__)
    shared_args = {**cli_args, **answer_file_args}
    for arg, value in shared_args.items():
        print(f"{arg}: {value}")

