    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    required_list = []
    for option_spec in options_spec:
        args_values = {arg: arg for arg in option_spec.get('kwargs', []) if arg in args}
        if 'required_when' not in option_spec:
            continue

        for argument, condition in option_spec['required_when'].items():
            if argument not in args_values or not eval(condition, args_values):
                break
        else:
            required_list.append(argument)

    return required_list

