    for key, value in args.items():
        if not isinstance(value, (int, float)):
            raise TypeError(f"Argument '{key}' must be an integer or a float.")
        if 'minimum' not in args or 'maximum' not in args:
            raise ValueError(f"Minimum and maximum values must be provided for argument '{key}'.")

