class ComplexArgumentType:
    def __init__(self, value, subcommand, type_name, option_name, spec_option):
        self.value = value
        self.subcommand = subcommand
        self.type_name = type_name
        self.option_name = option_name
        self.spec_option = spec_option

    def __str__(self):
        return f"ComplexArgumentType(value={self.value}, subcommand={self.subcommand}, type_name={self.type_name}, option_name={self.option_name}, spec_option={self.spec_option})"

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    parts = type_name.split('.')
    if '.' not in type_name or len(parts) < 2:
        raise ValueError("Invalid complex type name")
    module_name = '.'.join(parts[:-1])
    class_name = parts[-1]

    try:
        module = __import__(module_name, fromlist=[''])
        complex_type = getattr(module, class_name)
    except (ImportError, AttributeError):
        raise ValueError(f"Complex type not found: {type_name}")

    if hasattr(complex_type, 'SPEC_OPTION'):
        setattr(complex_type, '@complex_type', spec_option)

    if hasattr(complex_type, 'factory'):
        # Assuming complex_type has a factory attribute
        factory_args = getattr(complex_type, 'factory')()
        return complex_type(**factory_args)
    else:
        raise ValueError(f"Unsupported complex type: {type_name}")

