def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    playbk = os.path.join(ir_workspace, 'playbooks', ir_plugin.playbook)
    command = ["ansible-playbook", "-vvvvv"] + cli_args + [playbk]
    command.extend(["--extra-vars", quote(vars_dict)])

    try:
        logger.debug("Executing Ansible call `%s`", " ".join(command))
        proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out, err = proc.communicate()

        if code := proc.returncode:
            logger.error(f"Error executing Ansible playbook '{ir_plugin.playbook}': {err.decode('utf-8')}")
            return {"status": "failed", "message": err.decode('utf-8')}

        return {"status": "success", "message": out.decode('utf-8')}
    except Exception as e:
        logger.error(f"Failed to execute Ansible playbook '{ir_plugin.playbook}': {e}")
        return {"status": "failed", "message": str(e)}

